#include <iostream>
#include <string>

int main() {
    // Read input
    std::string inp;
    std::getline(std::cin, inp);

    // Replace first 'at' with '@'
    size_t pos = inp.find("at");
    if (pos != std::string::npos) {
        inp.replace(pos, 2, "@");
    }

    // If string starts with '@', prepend 'at' and replace next 'at'
    if (!inp.empty() && inp[0] == '@') {
        size_t second_at_pos = inp.find("at", 1);
        if (second_at_pos != std::string::npos) {
            inp.replace(second_at_pos, 2, "@");
        }
        inp = "at" + inp.substr(1);
    }

    // Replace 'dot' with '.' and handle start/end dots
    size_t dot_pos;
    while ((dot_pos = inp.find("dot")) != std::string::npos) {
        inp.replace(dot_pos, 3, ".");
    }

    // Handle start with '.'
    if (!inp.empty() && inp.front() == '.') {
        inp.replace(0, 1, "dot");
    }

    // Handle end with '.'
    if (!inp.empty() && inp.back() == '.') {
        inp.pop_back();
        inp += "dot";
    }

    std::cout << inp << std::endl;
    return 0;
}
